-- MB Events schema (PostgreSQL / Supabase).
-- Ids are UUIDs generated by the app; timestamps are timestamptz; structured blobs are jsonb.

-- Website inquiries -------------------------------------------------------

CREATE TABLE leads (
  id uuid PRIMARY KEY,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  stage text NOT NULL DEFAULT 'new_lead' CHECK (stage IN (
    'new_lead', 'attempted_contact', 'contacted', 'consultation_scheduled', 'consultation_completed', 'proposal_sent',
    'follow_up', 'deposit_pending', 'booked', 'event_planning', 'event_completed', 'review_requested', 'referral', 'lost')),
  source text NOT NULL CHECK (source IN ('builder', 'availability', 'venue', 'contact', 'blueprint')),
  name text NOT NULL,
  email text NOT NULL DEFAULT '',
  phone text NOT NULL DEFAULT '',
  event_type text NOT NULL,
  event_date date,
  guest_count text,
  location text,
  venue_status text CHECK (venue_status IN ('selected', 'need_venue', 'deciding')),
  vibe text,
  priorities jsonb NOT NULL DEFAULT '[]'::jsonb,
  contact_method text NOT NULL DEFAULT 'either' CHECK (contact_method IN ('phone', 'email', 'either')),
  campaign text,
  notes text
);
CREATE INDEX leads_created_at_idx ON leads (created_at DESC);
CREATE INDEX leads_stage_created_at_idx ON leads (stage, created_at DESC);
CREATE INDEX leads_email_source_idx ON leads (lower(email), source, created_at DESC);

CREATE TABLE analytics_events (
  id uuid PRIMARY KEY,
  created_at timestamptz NOT NULL DEFAULT now(),
  event_name text NOT NULL,
  source text,
  lead_id uuid REFERENCES leads (id) ON DELETE CASCADE,
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb
);
CREATE INDEX analytics_events_name_created_idx ON analytics_events (event_name, created_at DESC);

-- Admin accounts, sessions, audit ------------------------------------------

CREATE TABLE admin_users (
  email text PRIMARY KEY CHECK (email = lower(email)),
  name text NOT NULL DEFAULT '',
  password_hash text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by text NOT NULL
);

CREATE TABLE admin_sessions (
  token_hash text PRIMARY KEY,
  email text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL
);
CREATE INDEX admin_sessions_email_idx ON admin_sessions (email);
CREATE INDEX admin_sessions_expires_idx ON admin_sessions (expires_at);

CREATE TABLE admin_login_failures (
  email text PRIMARY KEY,
  failures integer NOT NULL DEFAULT 0,
  locked_until timestamptz
);

CREATE TABLE admin_audit (
  id uuid PRIMARY KEY,
  created_at timestamptz NOT NULL DEFAULT now(),
  actor_email text NOT NULL,
  action text NOT NULL,
  subject_id text NOT NULL,
  before_value jsonb,
  after_value jsonb
);
CREATE INDEX admin_audit_subject_created_idx ON admin_audit (subject_id, created_at DESC);

-- Client planner -----------------------------------------------------------

CREATE TABLE planner_events (
  id uuid PRIMARY KEY,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  code text NOT NULL UNIQUE,
  password_hash text NOT NULL,
  guest_code text NOT NULL UNIQUE,
  guest_password text NOT NULL,
  lead_id uuid REFERENCES leads (id) ON DELETE SET NULL,
  data jsonb NOT NULL,
  admin_data jsonb NOT NULL,
  failed_logins integer NOT NULL DEFAULT 0,
  locked_until timestamptz
);
CREATE INDEX planner_events_updated_idx ON planner_events (updated_at DESC);

CREATE TABLE planner_sessions (
  token_hash text PRIMARY KEY,
  event_id uuid NOT NULL REFERENCES planner_events (id) ON DELETE CASCADE,
  kind text NOT NULL CHECK (kind IN ('client', 'guest')),
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL
);
CREATE INDEX planner_sessions_event_idx ON planner_sessions (event_id);
CREATE INDEX planner_sessions_expires_idx ON planner_sessions (expires_at);

CREATE TABLE planner_guest_requests (
  id uuid PRIMARY KEY,
  event_id uuid NOT NULL REFERENCES planner_events (id) ON DELETE CASCADE,
  created_at timestamptz NOT NULL DEFAULT now(),
  guest_name text NOT NULL,
  title text NOT NULL,
  artist text NOT NULL DEFAULT '',
  note text NOT NULL DEFAULT '',
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'declined'))
);
CREATE INDEX planner_guest_requests_event_idx ON planner_guest_requests (event_id, created_at DESC);

CREATE TABLE planner_messages (
  id uuid PRIMARY KEY,
  event_id uuid NOT NULL REFERENCES planner_events (id) ON DELETE CASCADE,
  created_at timestamptz NOT NULL DEFAULT now(),
  sender text NOT NULL CHECK (sender IN ('client', 'mb')),
  body text NOT NULL,
  read_at timestamptz
);
CREATE INDEX planner_messages_event_idx ON planner_messages (event_id, created_at);

-- Request throttling (login and public form rate limits) -------------------

CREATE TABLE rate_limits (
  key text PRIMARY KEY,
  window_start timestamptz NOT NULL,
  hits integer NOT NULL DEFAULT 0
);
